/**
 * 世界书观测台网络同步加载器
 * Author: 砚梨
 */
(async () => {
  'use strict';

  const MANIFEST_URL = 'https://raw.githubusercontent.com/yanxu-orange/worldbook-observer-release/main/manifest.json';
  const RELEASE_URL_PATTERN = /^https:\/\/fastly\.jsdelivr\.net\/gh\/yanxu-orange\/worldbook-observer-release@v\d+\.\d+\.\d+\/releases\/v\d+\.\d+\.\d+\/index\.js$/u;
  const STATE_KEY = '__IWB_NETWORK_LOADER_STATE__';

  function hostWindow() {
    try {
      if (globalThis.parent && globalThis.parent !== globalThis && globalThis.parent.document) return globalThis.parent;
    } catch (_error) {}
    return globalThis;
  }

  function notify(kind, message) {
    const api = hostWindow().toastr || globalThis.toastr;
    if (api && typeof api[kind] === 'function') api[kind](message, '世界书观测台');
    else console[kind === 'error' ? 'error' : 'log'](`[世界书观测台] ${message}`);
  }

  async function sha256Hex(text) {
    if (!globalThis.crypto?.subtle || typeof TextEncoder !== 'function') throw new Error('当前浏览器不支持安全校验，请使用离线版。');
    const digest = await globalThis.crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
    return [...new Uint8Array(digest)].map(value => value.toString(16).padStart(2, '0')).join('').toUpperCase();
  }

  const previous = globalThis[STATE_KEY];
  if (previous?.status === 'loading' || previous?.status === 'loaded') return;
  globalThis[STATE_KEY] = { status: 'loading', version: null };

  try {
    const manifestResponse = await fetch(`${MANIFEST_URL}?t=${Date.now()}`, { cache: 'no-store' });
    if (!manifestResponse.ok) throw new Error(`版本清单读取失败（HTTP ${manifestResponse.status}）。`);
    const manifest = await manifestResponse.json();
    if (manifest?.schema !== 1 || manifest?.channel !== 'stable') throw new Error('版本清单格式无效。');
    if (typeof manifest.version !== 'string' || !/^\d+\.\d+\.\d+$/u.test(manifest.version)) throw new Error('版本号无效。');
    if (typeof manifest.entry !== 'string' || !RELEASE_URL_PATTERN.test(manifest.entry)) throw new Error('发行地址不受信任。');
    if (typeof manifest.sha256 !== 'string' || !/^[0-9A-F]{64}$/u.test(manifest.sha256)) throw new Error('发行校验值无效。');

    const scriptResponse = await fetch(manifest.entry, { cache: 'no-store' });
    if (!scriptResponse.ok) throw new Error(`稳定版下载失败（HTTP ${scriptResponse.status}）。`);
    const source = await scriptResponse.text();
    const actualHash = await sha256Hex(source);
    if (actualHash !== manifest.sha256) throw new Error('稳定版完整性校验失败，已停止执行。');

    new Function(`${source}\n//# sourceURL=${manifest.entry}`)();
    globalThis[STATE_KEY] = { status: 'loaded', version: manifest.version };
    notify('success', `网络稳定版 v${manifest.version} 已加载`);
  } catch (error) {
    globalThis[STATE_KEY] = { status: 'failed', version: null };
    const message = error instanceof Error ? error.message : String(error);
    notify('error', `${message} 请改用完整离线版。`);
  }
})();
